<?php class PaymentService{public static function createDemoPayment($studentId,$feeId,$amount,$ref=null){$ref=$ref?:'PAY-'.date('YmdHis').'-'.secure_random(4);db()->beginTransaction();try{$s=db()->prepare('INSERT INTO payments(student_id,student_fee_id,amount,reference,status,provider,paid_at) VALUES(?,?,?,?,?,?,NOW())');$s->execute([$studentId,$feeId,$amount,$ref,'Success','DemoGateway']);$p=(int)db()->lastInsertId();$u=db()->prepare("UPDATE student_fees SET paid_amount=LEAST(amount,paid_amount+?), status=CASE WHEN paid_amount+? >= amount THEN 'Paid' ELSE 'Pending' END WHERE id=?");$u->execute([$amount,$amount,$feeId]);$receipt='RCPT-'.date('Ymd').'-'.strtoupper(substr(hash('sha256',$ref),0,10));db()->prepare('INSERT INTO receipts(payment_id,receipt_no) VALUES(?,?)')->execute([$p,$receipt]);db()->commit();AuditService::log('PAYMENT','fees',$p,'Demo payment '.$ref.' receipt '.$receipt);return ['payment_id'=>$p,'receipt_no'=>$receipt];}catch(Throwable $e){db()->rollBack();throw $e;}}}
